 let red=0,green=0,blue=0,count=0;const torso=d.components[2].texture;
 for(let k=0;k<torso.rgba.length;k+=4){const r=torso.rgba[k],g=torso.rgba[k+1],b=torso.rgba[k+2];if(torso.rgba[k+3]>160&&r>110&&g>75&&r>g*1.12&&g>b*1.3){red+=r;green+=g;blue+=b;count++;}}
 d.sleeve=new Uint8Array(count?[Math.round(red/count),Math.round(green/count),Math.round(blue/count)]:[188,145,67]);d.sleeveFar=new Uint8Array([d.sleeve[0]-15,d.sleeve[1]-16,d.sleeve[2]-11]);
 d.texture={id:'fidelity-worker-composite',dx:-16,dy:-34,x:0,y:0,w:32,h:36,width:128,height:144,rgba:new Uint8ClampedArray(128*144*4),pixels:new Uint8Array(128*144).fill(EMPTY)};
 d.underIdx=new Uint8Array(1152);d.underLvl=new Uint8Array(1152);d.underDep=new Int16Array(1152);d.savedIdx=new Uint8Array(1152);d.savedLvl=new Uint8Array(1152);d.savedDep=new Int16Array(1152);d.owned=new Uint8Array(1152);d.active=false;d.underFrames=0;d.latePoints=0;
 d.retainedBytes=10368+d.parts.byteLength+d.texture.rgba.byteLength+d.texture.pixels.byteLength+d.sleeve.byteLength+d.sleeveFar.byteLength;OFFICE_FIDELITY.workerBytes=d.retainedBytes;
 const nativeLeg=leg,nativeArm=arm,nativeTpl=tpl,nativeSatchel=satchel,nativeHeld=heldItem,nativeBuild=buildSorter;
 leg=function(hx,hy,fdx,fdy,near,toLeft){fidelityWorkerPart(1,hx,hy,fdx,fdy,near,toLeft);return nativeLeg(hx,hy,fdx,fdy,near,toLeft);};
 arm=function(sx,sy,hx,hy,near){fidelityWorkerPart(2,sx,sy,hx,hy,near);return nativeArm(sx,sy,hx,hy,near);};
 tpl=function(rows,x,y){if(rows===A_TORSO||rows===B_TORSO)fidelityWorkerPart(3,x,y,rows===B_TORSO);else if(rows===A_HEAD||rows===B_HEAD)fidelityWorkerPart(5,x,y,rows===B_HEAD);return nativeTpl(rows,x,y);};
 satchel=function(x,y){fidelityWorkerPart(4,x,y);return nativeSatchel(x,y);};
 heldItem=function(x,y){fidelityWorkerPart(6,x,y,pose.item,pose.itemF);const active=d.inItem;d.inItem=true;try{return nativeHeld(x,y);}finally{d.inItem=active;}};
