  if(!d.enabled||!trainRichOn()||ACTIVE_ROOM.id!=='train'||paperAtlasBuilding)return nativeBuild();
  d.count=0;d.look=pose.look;d.scratch=pose.scratch;d.capturing=true;try{nativeBuild();}finally{d.capturing=false;}
  fidelityWorkerCompose();window.__officeFidelityCat=d.texture;d.builds++;
