const CR={materials:{},under:[],pending:'',restored:0,withhold:false,ready:false};window.TRAIN_CRAFT=CR;
function craftArea(token,x,y,w,h){const n=w*h*16;return {token,x,y,ox:x-OX,oy:y-OY,w,h,idx:new Uint8Array(n),lvl:new Uint8Array(n),dep:new Int16Array(n),rgb:new Uint32Array(n),pos:new Uint32Array(n),count:0,coarseIdx:new Uint8Array(w*h),coarseDep:new Int16Array(w*h)};}
