 const build=buildTrainProp;buildTrainProp=function(kind,frame){CR.pending=kind;return build(kind,frame);};const spr=depotSpriteAt;depotSpriteAt=function(x,y,z){if(CR.pending!=='parcel-stack'||!polishStaticOn())return spr(x,y,z);return craftCapture(parcel,()=>spr(x,y,z));};
